//! 📽️ Master/layout/slide relationships, authored shapes and embedded typed document blocks.
use crate::standards::v1::subsets::base::schema::snapshot::sqlite::native::Bound;
use semio_framework_os_kernel::sqlite_snapshot::artifact::{FloatColumn,FloatRow as SqliteRow,insert_ieee754,insert_key_ieee754};
use crate::standards::v1::subsets::base::schema::snapshot::native_decoding::Owned;
use super::{SemioPresentationSnapshot,SlideMaster,SlideLayout,Slide,SlideShape,SlideFrame,SlidePictureImage,SlideTableRow,SlideTableCell,PlaceholderKind,SemioPoint2};
use crate::standards::v1::subsets::document::schema::snapshot::sqlite::{DocSqliteTables,project_block_collection,reconstruct_block_collections};
use semio_framework_os_kernel::{ArtifactSqliteSnapshot,sqlite_snapshot::{artifact::{Cell,Projection,Reconstruction},validate_sqlite_database_schema,SqliteDatabase,SqliteValue,SqliteSnapshotControl,SqliteSnapshotPhase}};
use std::collections::{BTreeMap,BTreeSet};
const BLOCKS:DocSqliteTables=DocSqliteTables{collection:"semio_presentation_collection",member:"semio_presentation_member",block:"semio_presentation_block",paragraph:"semio_presentation_paragraph",heading:"semio_presentation_heading",run:"semio_presentation_run",list:"semio_presentation_list",list_item:"semio_presentation_list_item",table:"semio_presentation_table",table_row:"semio_presentation_table_row",table_cell:"semio_presentation_table_cell",code:"semio_presentation_code",quote:"semio_presentation_quote",image_block:"semio_presentation_image_block",page_break:"semio_presentation_page_break"};
fn number(n:usize)->Result<i64,String>{i64::try_from(n).map_err(|e|e.to_string())}
fn identity<'a>(row:impl std::borrow::Borrow<SqliteRow<'a>>,n:usize)->Result<(),String>{let row=*row.borrow();if row.rowid<=0||row.integer(0)?!=row.rowid||row.values.len()!=n{Err("invalid presentation row identity or columns".into())}else{Ok(())}}
fn optional_integer(row:SqliteRow<'_>,i:usize)->Result<Option<i64>,String>{if row.is_null(i)?{Ok(None)}else{row.integer(i).map(Some)}}
fn names<'a>(rows:&[SqliteRow<'a>],columns:usize)->Result<BTreeMap<i64,&'a str>,String>{let mut result=BTreeMap::new();let mut names=BTreeSet::new();for row in rows{identity(row,columns)?;if row.integer(1)?!=1||result.insert(row.rowid,row.text(3)?).is_some()||!names.insert(row.text(3)?){return Err("invalid presentation native identity or owner".into());}}Ok(result)}
fn details<'a>(db:&'a SqliteDatabase,name:&str,n:usize,c:&mut SqliteSnapshotControl<'_>)->Result<BTreeMap<i64,SqliteRow<'a>>,String>{let mut result=BTreeMap::new();for(count,row)in float_rows(db,name,c)?.into_iter().enumerate(){identity(row,n)?;if result.insert(row.rowid,row).is_some(){return Err("duplicate presentation identity".into());}if count%256==0{c.checkpoint(SqliteSnapshotPhase::ReconstructSnapshot,count,0)?;}}Ok(result)}
fn ordered<'a>(mut rows:Vec<SqliteRow<'a>>,i:usize)->Result<Vec<SqliteRow<'a>>,String>{rows.sort_by_key(|r|r.integer(i).unwrap_or(-1));for(n,r)in rows.iter().enumerate(){if r.integer(i)?!=number(n)?{return Err("presentation order must be contiguous".into());}}Ok(rows)}
fn groups<'a>(db:&'a SqliteDatabase,name:&str,n:usize,parents:&BTreeMap<i64,SqliteRow<'_>>,c:&mut SqliteSnapshotControl<'_>)->Result<BTreeMap<i64,Vec<SqliteRow<'a>>>,String>{let mut result=BTreeMap::<i64,Vec<SqliteRow<'_>>>::new();for row in details(db,name,n,c)?.into_values(){if !parents.contains_key(&row.integer(1)?){return Err("dangling presentation relationship owner".into());}row.integer(2)?;result.entry(row.integer(1)?).or_default().push(row);}for rows in result.values_mut(){*rows=ordered(std::mem::take(rows),2)?;}Ok(result)}
fn project_shapes(shapes:&[SlideShape],owner:(Option<i64>,Option<i64>,Option<i64>),p:&mut Projection<'_,'_>)->Result<(),String>{for(ordinal,shape)in shapes.iter().enumerate(){let(kind,frame)=match shape{SlideShape::TextBox{frame,..}=>("textBox",frame),SlideShape::Picture{frame,..}=>("picture",frame),SlideShape::Table{frame,..}=>("table",frame),SlideShape::Placeholder{frame,..}=>("placeholder",frame)};let id=p.insert_float("semio_presentation_shape",&[owner.0.map(Cell::Integer).unwrap_or(Cell::Null),owner.1.map(Cell::Integer).unwrap_or(Cell::Null),owner.2.map(Cell::Integer).unwrap_or(Cell::Null),Cell::Integer(number(ordinal)?),Cell::Text(kind),Cell::Real(frame.origin.x),Cell::Real(frame.origin.y),Cell::Real(frame.width),Cell::Real(frame.height)])?;match shape{
SlideShape::TextBox{blocks,..}=>{let collection=project_block_collection(blocks,BLOCKS,None,None,p)?;p.insert_key_float("semio_presentation_text_box",id,&[Cell::Integer(collection)])?;},
SlideShape::Picture{image,..}=>p.insert_key_float("semio_presentation_picture",id,&[Cell::Text(&image.asset_id),Cell::Text(&image.mime),Cell::Blob(&image.bytes)])?,
SlideShape::Table{rows,..}=>{p.insert_key_float("semio_presentation_shape_table",id,&[])?;for(ordinal,row)in rows.iter().enumerate(){let rid=p.insert_float("semio_presentation_shape_table_row",&[Cell::Integer(id),Cell::Integer(number(ordinal)?)])?;for(ordinal,cell)in row.cells.iter().enumerate(){let collection=project_block_collection(&cell.blocks,BLOCKS,None,None,p)?;p.insert_float("semio_presentation_shape_table_cell",&[Cell::Integer(rid),Cell::Integer(number(ordinal)?),Cell::Integer(collection)])?;}}},
SlideShape::Placeholder{kind,..}=>{let(tag,other)=match kind{PlaceholderKind::Title=>("title",None),PlaceholderKind::Subtitle=>("subtitle",None),PlaceholderKind::Body=>("body",None),PlaceholderKind::Footer=>("footer",None),PlaceholderKind::SlideNumber=>("slideNumber",None),PlaceholderKind::DateTime=>("dateTime",None),PlaceholderKind::Other{value}=>("other",Some(value.as_str()))};p.insert_key_float("semio_presentation_placeholder",id,&[Cell::Text(tag),other.map(Cell::Text).unwrap_or(Cell::Null)])?;}}}Ok(())}
impl ArtifactSqliteSnapshot for SemioPresentationSnapshot{
fn retire_sqlite_snapshot(self){drop(crate::standards::v1::subsets::base::schema::snapshot::native_decoding::Owned::new(self));}

fn encode_sqlite_snapshot_native(&self,encoding:store::sqlite_snapshot::SnapshotEncoding,control:&mut SqliteSnapshotControl<'_>)->Result<store::os_io::IoPayload,String>{super::native_encoding::encode(self,encoding,control)}
fn decode_sqlite_snapshot_native(payload:&store::os_io::IoPayload,control:&mut SqliteSnapshotControl<'_>)->Result<Self,String>{super::native_decoding::decode(payload,control)}
fn preflight_sqlite_snapshot_encoding(&self,_encoding:semio_framework_os_kernel::sqlite_snapshot::SnapshotEncoding,control:&mut SqliteSnapshotControl<'_>)->Result<(),String>{let mut b=Bound::new("",control)?;self.native_fields(&mut b)?;b.finish()}

fn validate_sqlite_snapshot_subset(&self,dialect:&store::os_io::ArtifactDialect,database:&SqliteDatabase,control:&mut SqliteSnapshotControl<'_>)->semio_framework_os_kernel::io_schema::IoResult<()>{
control.checkpoint(SqliteSnapshotPhase::ProjectSnapshot,0,1)?;
if dialect.artifact_kind!="s.stdio.semio"||dialect.standard!="v1"||(dialect.subset!="*"&&dialect.subset!="presentation"){return Err(String::from("Semio owned snapshot dialect differs from its dedicated semantic subset").into());}
let row=database.table("semio_presentation_document")?.single_row()?;
if row.rowid!=1||row.integer(0)?!=1||row.text(1)?!=self.schema{return Err(String::from("Semio owned document identity differs from projected semantic fields").into());}
control.checkpoint(SqliteSnapshotPhase::ProjectSnapshot,1,1)?;Ok(semio_framework_os_kernel::io_schema::IoOutcome::clean(()))}

const SQLITE_SCHEMA:&'static str=include_str!("🗄️.sql");
fn to_sqlite_database(&self,c:&mut SqliteSnapshotControl<'_>)->Result<SqliteDatabase,String>{let mut p=Projection::new(Self::SQLITE_SCHEMA,c)?;p.insert_key_float("semio_presentation_document",1,&[Cell::Text(&self.schema)])?;let mut masters=BTreeMap::new();let mut layouts=BTreeMap::new();let mut slides=BTreeSet::new();for(ordinal,m)in self.masters.iter().enumerate(){let id=p.insert_float("semio_presentation_master",&[Cell::Integer(1),Cell::Integer(number(ordinal)?),Cell::Text(&m.id)])?;if masters.insert(m.id.as_str(),id).is_some(){return Err("duplicate presentation master identity".into());}project_shapes(&m.shapes,(Some(id),None,None),&mut p)?;}for(ordinal,l)in self.layouts.iter().enumerate(){let master=*masters.get(l.master_id.as_str()).ok_or("dangling presentation layout master")?;let id=p.insert_float("semio_presentation_layout",&[Cell::Integer(1),Cell::Integer(number(ordinal)?),Cell::Text(&l.id),Cell::Integer(master)])?;if layouts.insert(l.id.as_str(),id).is_some(){return Err("duplicate presentation layout identity".into());}project_shapes(&l.shapes,(None,Some(id),None),&mut p)?;}for(ordinal,s)in self.slides.iter().enumerate(){if !slides.insert(s.id.as_str()){return Err("duplicate presentation slide identity".into());}let layout=s.layout_id.as_deref().map(|id|layouts.get(id).copied().ok_or("dangling presentation slide layout")).transpose()?;let notes=project_block_collection(&s.notes,BLOCKS,None,None,&mut p)?;let id=p.insert_float("semio_presentation_slide",&[Cell::Integer(1),Cell::Integer(number(ordinal)?),Cell::Text(&s.id),layout.map(Cell::Integer).unwrap_or(Cell::Null),Cell::Integer(notes)])?;project_shapes(&s.shapes,(None,None,Some(id)),&mut p)?;}p.finish()}
fn from_sqlite_database(db:&SqliteDatabase,c:&mut SqliteSnapshotControl<'_>)->Result<Self,String> { Self::reconstruct_sqlite_database(db, c, Self::SQLITE_SCHEMA) }
}

impl SemioPresentationSnapshot {
    /// 🧩️ Restores the owned typed subset inside its independently declared relational composition.
    pub fn reconstruct_sqlite_database(db:&SqliteDatabase,c:&mut SqliteSnapshotControl<'_>, declared_schema: &str)->Result<Self,String> {
c.check_database(db,SqliteSnapshotPhase::ReconstructSnapshot)?;validate_sqlite_database_schema(db,declared_schema,c.limits()).map_err(|e|e.to_string())?;let doc=single_float_row(db,"semio_presentation_document")?;identity(doc,2)?;if doc.rowid!=1{return Err("invalid presentation document identity".into());}let master_rows=ordered_float_rows(db,"semio_presentation_master",2,c)?;let layout_rows=ordered_float_rows(db,"semio_presentation_layout",2,c)?;let slide_rows=ordered_float_rows(db,"semio_presentation_slide",2,c)?;let master_names=names(&master_rows,4)?;let layout_names=names(&layout_rows,5)?;let slide_names=names(&slide_rows,6)?;
let shapes=details(db,"semio_presentation_shape",10,c)?;let mut text_boxes=details(db,"semio_presentation_text_box",2,c)?;let mut pictures=details(db,"semio_presentation_picture",4,c)?;let mut tables=details(db,"semio_presentation_shape_table",1,c)?;let mut placeholders=details(db,"semio_presentation_placeholder",3,c)?;let mut table_rows=groups(db,"semio_presentation_shape_table_row",3,&tables,c)?;let raw_table_rows=details(db,"semio_presentation_shape_table_row",3,c)?;let mut table_cells=groups(db,"semio_presentation_shape_table_cell",4,&raw_table_rows,c)?;
let mut owners=BTreeMap::<(u8,i64),Vec<SqliteRow<'_>>>::new();for row in shapes.into_values(){let master=optional_integer(row,1)?;let layout=optional_integer(row,2)?;let slide=optional_integer(row,3)?;let owner=match(master,layout,slide){(Some(id),None,None)if master_names.contains_key(&id)=>(0,id),(None,Some(id),None)if layout_names.contains_key(&id)=>(1,id),(None,None,Some(id))if slide_names.contains_key(&id)=>(2,id),_=>return Err("presentation shape requires one declared owner".into())};row.integer(4)?;owners.entry(owner).or_default().push(row);}
let mut roots=Vec::new();for row in text_boxes.values(){roots.push(row.integer(1)?);}for rows in table_cells.values(){for row in rows{roots.push(row.integer(3)?);}}for slide in &slide_rows{roots.push(slide.integer(5)?);}let mut native_blocks=Owned::new(reconstruct_block_collections(db,BLOCKS,&roots,None,None,c)?);native_blocks.get_mut().reverse();let mut block_collections=Owned::new(BTreeMap::new());for root in roots{block_collections.get_mut().insert(root,native_blocks.get_mut().pop().ok_or("missing presentation collection")?);}let mut restore=Reconstruction::new(c)?;let mut native_shapes=Owned::new(BTreeMap::<(u8,i64),Vec<SlideShape>>::new());for(owner,rows)in owners{let mut native=Owned::new(Vec::new());for row in ordered(rows,4)?{let id=row.rowid;let frame=SlideFrame{origin:SemioPoint2{x:row.real(6)?,y:row.real(7)?},width:row.real(8)?,height:row.real(9)?};let shape=match row.text(5)?{
"textBox"=>{let a=text_boxes.remove(&id).ok_or("missing presentation text box fields")?;SlideShape::TextBox{frame,blocks:block_collections.get_mut().remove(&a.integer(1)?).ok_or("missing text box block collection")?}},
"picture"=>{let a=pictures.remove(&id).ok_or("missing presentation picture fields")?;SlideShape::Picture{frame,image:SlidePictureImage{asset_id:restore.text(a.text(1)?)?,mime:restore.text(a.text(2)?)?,bytes:restore.blob(a.blob(3)?)?}}},
"table"=>{tables.remove(&id).ok_or("missing presentation table fields")?;let mut rows=Owned::new(Vec::new());for a in table_rows.remove(&id).unwrap_or_default(){let mut cells=Owned::new(Vec::new());for cell in table_cells.remove(&a.rowid).unwrap_or_default(){cells.get_mut().push(SlideTableCell{blocks:block_collections.get_mut().remove(&cell.integer(3)?).ok_or("missing slide table cell blocks")?});}rows.get_mut().push(SlideTableRow{cells:cells.take()});}SlideShape::Table{frame,rows:rows.take()}},
"placeholder"=>{let a=placeholders.remove(&id).ok_or("missing presentation placeholder fields")?;let other=a.optional_text(2)?;let kind=match(a.text(1)?,other){("title",None)=>PlaceholderKind::Title,("subtitle",None)=>PlaceholderKind::Subtitle,("body",None)=>PlaceholderKind::Body,("footer",None)=>PlaceholderKind::Footer,("slideNumber",None)=>PlaceholderKind::SlideNumber,("dateTime",None)=>PlaceholderKind::DateTime,("other",Some(value))=>PlaceholderKind::Other{value:restore.text(value)?},_=>return Err("invalid presentation placeholder shape".into())};SlideShape::Placeholder{frame,kind}},_=>return Err("unknown presentation shape kind".into())};native.get_mut().push(shape);restore.checkpoint()?;}native_shapes.get_mut().insert(owner,native.take());}
if !text_boxes.is_empty()||!pictures.is_empty()||!tables.is_empty()||!placeholders.is_empty()||!table_rows.is_empty()||!table_cells.is_empty(){return Err("orphan or contradictory presentation shape detail".into());}let mut masters=Owned::new(Vec::new());for row in master_rows{masters.get_mut().push(SlideMaster{id:restore.text(row.text(3)?)?,shapes:native_shapes.get_mut().remove(&(0,row.rowid)).unwrap_or_default()});}let mut layouts=Owned::new(Vec::new());for row in layout_rows{layouts.get_mut().push(SlideLayout{id:restore.text(row.text(3)?)?,master_id:restore.text(master_names.get(&row.integer(4)?).ok_or("dangling presentation layout master")?)?,shapes:native_shapes.get_mut().remove(&(1,row.rowid)).unwrap_or_default()});}let mut slides=Owned::new(Vec::new());for row in slide_rows{let notes=Owned::new(block_collections.get_mut().remove(&row.integer(5)?).ok_or("missing presentation notes")?);slides.get_mut().push(Slide{id:restore.text(row.text(3)?)?,layout_id:optional_integer(row,4)?.map(|id|restore.text(layout_names.get(&id).ok_or("dangling presentation slide layout")?)).transpose()?,shapes:native_shapes.get_mut().remove(&(2,row.rowid)).unwrap_or_default(),notes:notes.take()});}if !native_shapes.get_mut().is_empty()||!block_collections.get_mut().is_empty(){return Err("orphan presentation content".into());}let value=Owned::new(Self{schema:restore.text(doc.text(1)?)?,masters:masters.take(),layouts:layouts.take(),slides:slides.take()});restore.checkpoint()?;Ok(value.take())
    }
}

fn float_columns(table:&str)->&'static [FloatColumn]{match table{"semio_presentation_shape"=>&[FloatColumn::Binary64(6),FloatColumn::Binary64(7),FloatColumn::Binary64(8),FloatColumn::Binary64(9)],"semio_presentation_run"=>&[FloatColumn::Binary64(7)],"semio_presentation_image_block"=>&[FloatColumn::Binary64(3),FloatColumn::Binary64(4)],_=>&[]}}
trait FloatProjection { fn insert_float(&mut self,table:&str,cells:&[Cell<'_>])->Result<i64,String>; fn insert_key_float(&mut self,table:&str,key:i64,cells:&[Cell<'_>])->Result<(),String>; }
impl FloatProjection for Projection<'_,'_> { fn insert_float(&mut self,table:&str,cells:&[Cell<'_>])->Result<i64,String>{insert_ieee754(self,table,cells,float_columns(table))} fn insert_key_float(&mut self,table:&str,key:i64,cells:&[Cell<'_>])->Result<(),String>{insert_key_ieee754(self,table,key,cells,float_columns(table))} }
fn float_rows<'a>(db:&'a SqliteDatabase,table:&str,control:&mut SqliteSnapshotControl<'_>)->Result<Vec<SqliteRow<'a>>,String>{let table_rows=db.table(table)?;control.check_rows(table_rows.rows.len())?;control.checkpoint(SqliteSnapshotPhase::ReconstructSnapshot,0,table_rows.rows.len())?;let mut result=Vec::new();for(count,row)in table_rows.rows.iter().enumerate(){result.push(SqliteRow::new(row,float_columns(table))?);if count%256==0{control.checkpoint(SqliteSnapshotPhase::ReconstructSnapshot,count,table_rows.rows.len())?;}}Ok(result)}
fn ordered_float_rows<'a>(db:&'a SqliteDatabase,table:&str,ordinal:usize,control:&mut SqliteSnapshotControl<'_>)->Result<Vec<SqliteRow<'a>>,String>{let mut result=Vec::new();for(count,row)in semio_framework_os_kernel::sqlite_snapshot::artifact::ordered_row_refs(db.table(table)?,ordinal,control)?.into_iter().enumerate(){result.push(SqliteRow::new(row,float_columns(table))?);if count%256==0{control.checkpoint(SqliteSnapshotPhase::ReconstructSnapshot,count,0)?;}}Ok(result)}
fn single_float_row<'a>(db:&'a SqliteDatabase,table:&str)->Result<SqliteRow<'a>,String>{SqliteRow::new(db.table(table)?.single_row()?,float_columns(table))}

impl SemioPresentationSnapshot{
/// 📏️ Bounds explicitly owned native fields before encoding.
pub fn native_fields(&self,b:&mut Bound<'_,'_>)->Result<(),String>{b.text(&self.schema)?;b.entities(self.masters.len())?;for master in &self.masters{b.text(&master.id)?;native_shapes(&master.shapes,b)?;}b.entities(self.layouts.len())?;for layout in &self.layouts{b.text(&layout.id)?;b.text(&layout.master_id)?;native_shapes(&layout.shapes,b)?;}b.entities(self.slides.len())?;for slide in &self.slides{b.text(&slide.id)?;b.optional_text(slide.layout_id.as_deref())?;native_shapes(&slide.shapes,b)?;crate::standards::v1::subsets::document::schema::snapshot::sqlite::native_blocks(&slide.notes,b)?;}Ok(())}
}

fn native_shapes(shapes:&[SlideShape],b:&mut Bound<'_, '_>)->Result<(),String>{b.entities(shapes.len())?;for shape in shapes{b.scalars(4)?;match shape{SlideShape::TextBox{blocks,..}=>crate::standards::v1::subsets::document::schema::snapshot::sqlite::native_blocks(blocks,b)?,SlideShape::Picture{image,..}=>{b.text(&image.asset_id)?;b.text(&image.mime)?;b.bytes(&image.bytes)?;},SlideShape::Table{rows,..}=>{b.entities(rows.len())?;for row in rows{b.entities(row.cells.len())?;for cell in &row.cells{crate::standards::v1::subsets::document::schema::snapshot::sqlite::native_blocks(&cell.blocks,b)?;}}},SlideShape::Placeholder{kind,..}=>{b.scalars(1)?;if let PlaceholderKind::Other{value}=kind{b.text(value)?;}}}}Ok(())}
